export const AUDIO_BARS = [
  18, 31, 24, 39, 30, 43, 27, 18, 9, 29, 38, 24, 34, 18, 26, 37, 21, 14, 7, 11,
  22, 35, 18, 26, 41, 29, 17, 33,
];
export function audioClock(value?: number) {
  const seconds = Math.max(0, Math.round(value ?? 0));
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
}

export type AttachmentUploadKind = "file" | "link" | "image" | "audio";
export type AttachmentRejectReason = "too-large" | "max-files";
export type AttachmentUploadStatus =
  "idle" | "uploading" | "complete" | "failed";
export interface AttachmentUploadItem {
  id: string;
  name: string;
  kind: AttachmentUploadKind;
  size?: number;
  href?: string;
  previewUrl?: string;
  currentTime?: number;
  duration?: number;
  status?: AttachmentUploadStatus;
  error?: string;
  file?: File;
}

import {
  FileArchive,
  FileAudio,
  FileCode2,
  FileIcon,
  FileImage,
  FileSpreadsheet,
  FileText,
  FileVideo,
} from "lucide-vue-next";
import type { FileUploadItem, FileUploadStatus } from "./types";
export function formatBytes(bytes: number) {
  if (!Number.isFinite(bytes) || bytes <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"],
    index = Math.min(
      Math.floor(Math.log(bytes) / Math.log(1024)),
      units.length - 1,
    ),
    value = bytes / 1024 ** index;
  return `${value.toFixed(value >= 10 || index === 0 ? 0 : 1)} ${units[index]}`;
}
export function clampProgress(
  value: number | undefined,
  status: FileUploadStatus,
) {
  if (status === "success") return 100;
  return value === undefined || Number.isNaN(value)
    ? 0
    : Math.max(0, Math.min(100, value));
}
export function fileKind(item: FileUploadItem) {
  const value = item.name.includes(".")
    ? item.name.split(".").at(-1)
    : item.type?.split("/").at(-1);
  return value?.toUpperCase() ?? "FILE";
}
export function getFileIcon(item: FileUploadItem) {
  const extension = item.name.split(".").at(-1)?.toLowerCase() ?? "",
    mime = item.type ?? "";
  if (mime.startsWith("image/")) return FileImage;
  if (mime.startsWith("video/")) return FileVideo;
  if (mime.startsWith("audio/")) return FileAudio;
  if (
    mime.includes("zip") ||
    mime.includes("compressed") ||
    ["zip", "rar", "7z", "tar", "gz"].includes(extension)
  )
    return FileArchive;
  if (
    mime.includes("spreadsheet") ||
    mime.includes("excel") ||
    ["csv", "xls", "xlsx"].includes(extension)
  )
    return FileSpreadsheet;
  if (
    mime.includes("pdf") ||
    mime.startsWith("text/") ||
    ["pdf", "doc", "docx", "md", "txt"].includes(extension)
  )
    return FileText;
  if (
    [
      "css",
      "html",
      "js",
      "jsx",
      "json",
      "mdx",
      "ts",
      "tsx",
      "xml",
      "yaml",
      "yml",
    ].includes(extension)
  )
    return FileCode2;
  return FileIcon;
}
export const STATUS_LABEL = {
  queued: "Queued",
  uploading: "Uploading",
  success: "Uploaded",
  error: "Failed",
};
export const STATUS_TONE = {
  queued: "text-muted-foreground",
  uploading: "text-foreground",
  success: "text-emerald-600 dark:text-emerald-400",
  error: "text-destructive",
};

import { computed, ref, type Ref } from "vue";
export function useUploadList<T>(
  model: () => T[] | undefined,
  legacy: () => T[] | undefined,
  initial: T[],
  changed: (items: T[]) => void,
) {
  const local = ref(initial) as Ref<T[]>;
  const items = computed(() => model() ?? legacy() ?? local.value);
  function commit(next: T[]) {
    if (model() === undefined && legacy() === undefined) local.value = next;
    changed(next);
  }
  return { items, commit };
}
export function acceptsUpload(file: File, accept?: string) {
  if (!accept) return true;
  const name = file.name.toLowerCase(),
    mime = file.type.toLowerCase();
  for (const token of accept.split(",")) {
    const rule = token.trim().toLowerCase();
    if (
      rule.startsWith(".")
        ? name.endsWith(rule)
        : rule.endsWith("/*")
          ? mime.startsWith(rule.slice(0, -1))
          : mime === rule
    )
      return true;
  }
  return false;
}
export function useFileDrop(
  disabled: () => boolean,
  full: () => boolean,
  receive: (files: File[]) => void,
) {
  const dragging = ref(false);
  let depth = 0;
  function drag(event: DragEvent, action: "enter" | "over" | "leave" | "drop") {
    if (disabled() || full()) return;
    event.preventDefault();
    if (action === "enter") {
      depth++;
      dragging.value = true;
    } else if (action === "over") {
      if (event.dataTransfer) event.dataTransfer.dropEffect = "copy";
      dragging.value = true;
    } else if (action === "leave") {
      depth = Math.max(0, depth - 1);
      if (!depth) dragging.value = false;
    } else {
      depth = 0;
      dragging.value = false;
      receive(Array.from(event.dataTransfer?.files ?? []));
    }
  }
  return { dragging, drag };
}

export type FileUploadClassNames = {
